<?php
namespace Xdecaro\Component\Decarofinance\Administrator\View\Payments;
defined('_JEXEC') or die;
use Joomla\CMS\Factory; use Joomla\CMS\Language\Text; use Joomla\CMS\MVC\View\HtmlView as BaseHtmlView; use Joomla\CMS\Toolbar\ToolbarHelper;
final class HtmlView extends BaseHtmlView { public array $items=[]; public function display($tpl=null):void { if(!Factory::getApplication()->getIdentity()->authorise('core.manage','com_decarofinance')) throw new \RuntimeException(Text::_('JERROR_ALERTNOAUTHOR'),403); ToolbarHelper::title(Text::_('COM_DECAROFINANCE_PAYMENTS'),'credit'); $wa=Factory::getApplication()->getDocument()->getWebAssetManager(); $wa->getRegistry()->addExtensionRegistryFile('com_decarofinance'); $wa->useStyle('com_decarofinance.admin'); $component=Factory::getApplication()->bootComponent('com_decarofinance'); if(!$component instanceof \Xdecaro\Component\Decarofinance\Administrator\Extension\DecarofinanceComponent) throw new \RuntimeException('Finance component is unavailable.'); $this->items=$component->getFinanceQueryService()->listPayments(); parent::display($tpl); } }
